import pyomo.environ as pyo

DATA = {
    "projects": ["X", "Y", "Z"],
    "cost": {"X": 50, "Y": 70, "Z": 100},
    "min_invest": {"X": 80, "Y": 60, "Z": 40},
    "total_budget": 300,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["projects"])

    def _lb(m, i):
        return d["min_invest"][i]

    def _ub(m, i):
        return d["total_budget"]

    model.x = pyo.Var(
        model.I,
        domain=pyo.NonNegativeIntegers,
        bounds=lambda m, i: (_lb(m, i), _ub(m, i)),
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def total_budget_rule(m):
        return sum(m.x[i] for i in m.I) <= d["total_budget"]

    model.total_budget = pyo.Constraint(rule=total_budget_rule)

    def min_invest_rule(m, i):
        return m.x[i] >= d["min_invest"][i]

    model.min_invest = pyo.Constraint(model.I, rule=min_invest_rule)

    return model


