import pyomo.environ as pyo

DATA = {
    "projects": ["X", "Y", "Z"],
    "budget_max": 300,
    "min_invest": {"X": 80, "Y": 60, "Z": 40},
    "cost_per_unit": {"X": 50, "Y": 70, "Z": 100},
}


def build_model(data=None):
    d = data or DATA
    m = pyo.ConcreteModel()

    # Set of projects
    m.P = pyo.Set(initialize=d["projects"])

    # Variables: whole-number investments, at least the per-project minimum
    def x_bounds(m, p):
        return (d["min_invest"][p], None)

    m.x = pyo.Var(m.P, domain=pyo.NonNegativeIntegers, bounds=x_bounds)

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["cost_per_unit"][p] * m.x[p] for p in m.P)

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: total budget cannot exceed 300  (<=)
    def budget_rule(m):
        return sum(m.x[p] for p in m.P) <= d["budget_max"]

    m.budget = pyo.Constraint(rule=budget_rule)

    # Constraints: per-project minimum investment  (>=)
    def min_rule(m, p):
        return m.x[p] >= d["min_invest"][p]

    m.min_invest = pyo.Constraint(m.P, rule=min_rule)

    return m


